    /// <summary>moodlets</summary>
    public class D001_moodlets
    {

        [Fact(DisplayName = "moodlets > blood up hits harder; shaken and well rested change the wait between swings; cold slows walking")]
        public void T002_blood_up_hits_harder_shaken_and_well_rested_change_the_wait_()
        {
            var state = ScenarioMod.loadScenario(new Scenario { seed = 1, map = ["s.."] });
            var s = Js.NN(Js.Get(state.survivors, 0));
            expect(Moodlets.boostDamage(s, 100)).toBe(100);
            Mood.addThought(state, s, "bloodUp");
            expect(Moodlets.boostDamage(s, 100)).toBe(Moodlets.HARDER_PCT);
            Mood.addThought(state, s, "shaken");
            expect(Moodlets.swingWait(s, Jobs.GUARD_ATTACK_EVERY)).toBeGreaterThan(Jobs.GUARD_ATTACK_EVERY);
            s.thoughts = [];
            Mood.addThought(state, s, "wellRested");
            expect(Moodlets.swingWait(s, Jobs.GUARD_ATTACK_EVERY)).toBeLessThan(Jobs.GUARD_ATTACK_EVERY);
            var pace = Survivors.stepPace(state, s, new Point { x = Js.I(1), y = Js.I(0) });
            Mood.addThought(state, s, "cold");
            expect(Survivors.stepPace(state, s, new Point { x = Js.I(1), y = Js.I(0) })).toBe(pace + 1);
        }

        [Fact(DisplayName = "moodlets > a kill gets your blood up")]
        public void T003_a_kill_gets_your_blood_up()
        {
            var state = ScenarioMod.loadScenario(new Scenario { seed = 1, map = ["s."] });
            var s = Js.NN(Js.Get(state.survivors, 0));
            Commands.applyCommand(state, new Command { type = "spawnZombie", x = Js.I(1), y = Js.I(0) });
            var z = Js.NN(Js.Get(state.zombies, 0));
            z.kind = "static";
            z.health = 1;
            Commands.applyCommand(state, new Command { type = "takeControl", survivorId = s.id });
            expect(Commands.applyCommand(state, new Command { type = "swing", x = Js.I(1), y = Js.I(0) })).toMatchObject(Js.Obj(("ok", (object?)(true))));
            expect(Moodlets.boosted(s, "harder")).toBe(true);
        }
    }

    /// <summary>resolve</summary>
    public class D004_resolve
    {

        [Fact(DisplayName = "resolve > starts near the middle, the same for the same id")]
        public void T005_starts_near_the_middle_the_same_for_the_same_id()
        {
            expect(Resolve.startingResolve("s5")).toBe(Resolve.startingResolve("s5"));
            for (var n = 1; n < 50; n++)
            {
                expect(Resolve.startingResolve($"s{Js.Str(n)}")).toBeGreaterThanOrEqual(40);
                expect(Resolve.startingResolve($"s{Js.Str(n)}")).toBeLessThanOrEqual(60);
            }
        }

        [Fact(DisplayName = "resolve > drifts with mood at dawn")]
        public void T006_drifts_with_mood_at_dawn()
        {
            var state = ScenarioMod.loadScenario(new Scenario { seed = 1, map = ["s.s"] });
            var (a, b) = state.survivors;
            a.resolve = b.resolve = 50;
            Mood.addThought(state, a, "reunited");
            Mood.addThought(state, b, "lostFriend");
            state.tick = Js.I(Time.DAY_LENGTH);
            Resolve.dawnResolve(state);
            expect(a.resolve).toBeGreaterThan(50);
            expect(b.resolve).toBeLessThan(50);
        }

        [Fact(DisplayName = "resolve > the breaking may walk away in the night (never the one you control); the steeled do not break down")]
        public void T007_the_breaking_may_walk_away_in_the_night_never_the_one_you_co()
        {
            var state = ScenarioMod.loadScenario(new Scenario { seed = 1, map = ["s.s.s.s.s.s"] });
            foreach (var s in Js.Iter(state.survivors))
            {
                s.resolve = 0;
            }
            Commands.applyCommand(state, new Command { type = "takeControl", survivorId = Js.NN(Js.Get(state.survivors, 0)).id });
            state.tick = Js.I(Time.DAY_LENGTH);
            Tick.tick(state);
            expect(state.survivors.length).toBeLessThan(6);
            expect(state.survivors.some((s) => s.id == Js.NN(state.control).survivorId)).toBe(true);
            expect(state.items.filter((i) => i.kind == "corpse")).toEqual(Js.Arr([]));
            expect(state.events.some((e) => Js.T(new JsRegExp("walked away", "").test(e.message)))).toBe(true);
            expect(Resolve.STEELED).toBeGreaterThan(Resolve.BREAKING);
        }

        [Fact(DisplayName = "resolve > breaking under your control: some swings freeze")]
        public void T008_breaking_under_your_control_some_swings_freeze()
        {
            var state = ScenarioMod.loadScenario(new Scenario { seed = 1, map = ["s."] });
            var s = Js.NN(Js.Get(state.survivors, 0));
            s.resolve = 0;
            double froze = 0;
            for (var t = 0; t < 200; t++, state.tick++)
            {
                if (Resolve.freezes(state, s))
                {
                    froze++;
                }
            }
            expect(froze).toBeGreaterThan(20);
            expect(froze).toBeLessThan(90);
            Resolve.steel(s, 50);
            expect(Resolve.freezes(state, s)).toBe(false);
        }

        [Fact(DisplayName = "resolve > a request seen through lifts it; a friend dying cuts it")]
        public void T009_a_request_seen_through_lifts_it_a_friend_dying_cuts_it()
        {
            var state = ScenarioMod.loadScenario(new Scenario { seed = 1, map = ["s.s"] });
            var (a, b) = state.survivors;
            a.resolve = 50;
            a.opinions[Js.Idx(b.id)] = 60;
            Mood.mournDeath(state, b);
            expect(a.resolve).toBeLessThan(50);
        }
    }
